// Each note in a box of its own, wrapping, with a button to remove
// it at its top right while it is hovered.
let notes = v_flex()
    .id("git-scroll")
    .w_full()
    .flex_shrink(1.)
    .min_h_0()
    .gap(GAP)
    .overflow_y_scroll()
    .track_scroll(&self.scroll)
    .children(self.notes.iter().map(|row| {
        let id = row.id;
        let group = SharedString::from(format!("commit-note-{id}"));
        let note = div().id(("commit-note", id as usize));
        // Lets UI tests find the note; inert in normal builds.
        gpui_kit::TestSupportExt::test_support(note)
            .group(group.clone())
            .relative()
            .py_1()
            .pl_1p5()
            .pr_5()
            .bg(tabs)
            .child(flush(
                Textarea::new(&row.input)
                    .appearance(false)
                    .text_xs()
                    .line_height(NOTE_LINE_HEIGHT),
            ))
            .child(
                div()
                    .absolute()
                    .top_0()
                    .right_0()
                    .opacity(0.)
                    .group_hover(group, |style| style.opacity(1.))
                    .child(
                        Button::new(("remove-commit-note", id as usize))
                            .ghost()
                            .xsmall()
                            .rounded(ButtonRounded::None)
                            .icon(IconName::X)
                            .tooltip("Remove this note")
                            .on_click(
                                cx.listener(move |this, _, _, cx| this.remove_note(id, cx)),
                            ),
                    ),
            )
    }));
// The message, Generate, and Commit, fixed along the bottom.
let footer = v_flex()
    .id("git-footer")
    .flex_none()
    .gap(GAP)
    .child({
        let (height, _) = self.message_fit.heights(&self.message, window, cx);
        let message = div()
            .id("git-commit-message")
            .relative()
            .py(px(3.))
            .px_1p5()
            .bg(crate::theme::color(palette.darkest))
            // The tracker over the editor alone, not its padding.
            .child(
                flush(Editor::new(&self.message).appearance(false).h(height)).child(
                    GrowToFit::tracker(
                        &self.message,
                        cx.entity().downgrade(),
                        |this: &mut Self| &mut this.message_fit,
                    ),
                ),
            );
        // Lets UI tests find the message; inert in normal builds.
        gpui_kit::TestSupportExt::test_support(message)
    })
    .child(
        h_flex()
            .gap(GAP)
            .justify_between()
            .child(generate)
            .child(commit),
    );

// Only the notes scroll, between the summary and the message, with a
// scrollbar only while they overflow; the rest is always as tall as
// it needs, so the notes give up their room first.
let overflows = self.scroll.max_offset().y >= px(1.);
if !overflows && self.scroll.offset() != Point::default() {
    self.scroll.set_offset(Point::default());
}
let watch = {
    let scroll = self.scroll.clone();
    canvas(
        |_, _, _| {},
        move |_, _, window, _| {
            if (scroll.max_offset().y >= px(1.)) != overflows {
                window.refresh();
            }
        },
    )
    .absolute()
    .size_0()
};
// Lets UI tests find the notes; inert in normal builds.
let notes = gpui_kit::TestSupportExt::test_support(notes);
let notes = if overflows {
    crate::scrollbar::with_fitted_scrollbar("git-scroll", &self.scroll, notes, cx)
} else {
    notes.into_any_element()
};
let body = v_flex()
    .id("git-body")
    .relative()
    .w_full()
    .flex_shrink(1.)
    .min_h_0()
    .px(PADDING)
    .pb(PADDING)
    .gap(GAP)
    .bg(crate::theme::color(palette.ribbon))
    .child(div().flex_none().child(summary_row))
    .when(!self.notes.is_empty(), |body| body.child(notes))
    .child(gpui_kit::TestSupportExt::test_support(footer))
    .child(watch);
// No line above it, nor between its header and body: the change of
// colour is the edge. It is as tall as its contents until its sidebar
// gives it less, on the body's colour all the way down.
let panel = v_flex()
    .id("git-panel")
    .w_full()
    .flex_shrink(1.)
    .min_h_0()
    .text_sm()
    .bg(crate::theme::color(palette.ribbon))
    .child(gpui_kit::TestSupportExt::test_support(header))

